from __future__ import annotations

import pytest
from nexus.engine.capability_contracts import CapabilityReceipt


def test_gate_passed_contract_without_telemetry():
    """M3 Layer 1: Verify gate_passed and evidence_present pass on mock fixtures without telemetry,

    but public_claim_safe remains strictly False to isolate production claims from mock runs.
    """
    # Simulate a mock receipt generated by the test runner (no telemetry, but gates pass)
    receipt = CapabilityReceipt(
        name="artifact_gate",
        selected=True,
        invoked=True,
        evidence_present=True,
        gate_passed=True,
        outcome_contributed=True,
        evidence_alignment=True,
        telemetries={},  # Empty telemetry in mock/dry-runs
    )

    # Basic ok flags should pass
    assert receipt.evidence_present is True
    assert receipt.gate_passed is True

    # Critical physical boundary check: must not allow public claim promotion without telemetry
    assert receipt.public_claim_safe is False, "Empty telemetry must fail public_claim_safe"


def test_public_claim_safe_contract_with_valid_telemetry():
    """M3 Layer 2: Verify public_claim_safe upgrades to True under fully complete,

    valid, non-outlier runtime telemetry.
    """
    # Simulate a production receipt with pristine measured telemetry
    receipt = CapabilityReceipt(
        name="artifact_gate",
        selected=True,
        invoked=True,
        evidence_present=True,
        gate_passed=True,
        outcome_contributed=True,
        evidence_alignment=True,
        telemetries={
            "telemetry_source": "measured",
            "has_infra_invalid": False,
            "model_calls": 1,
            "token_usage": 1234,
            "wall_time_ms": 1500,
            "provider_costs": 0.05,
            "overhead_ms": 200,
        },
    )

    assert receipt.evidence_present is True
    assert receipt.gate_passed is True
    assert receipt.public_claim_safe is True, "Valid complete telemetry must promote to public_claim_safe"


@pytest.mark.parametrize(
    "invalid_telemetry, reason",
    [
        (
            {
                "telemetry_source": "estimated",  # Estimated is forbidden
                "has_infra_invalid": False,
                "model_calls": 1,
                "token_usage": 1234,
                "wall_time_ms": 1500,
                "provider_costs": 0.05,
                "overhead_ms": 200,
            },
            "Estimated telemetry source",
        ),
        (
            {
                "telemetry_source": "measured",
                "has_infra_invalid": True,  # Infra invalid exists
                "model_calls": 1,
                "token_usage": 1234,
                "wall_time_ms": 1500,
                "provider_costs": 0.05,
                "overhead_ms": 200,
            },
            "Infra invalid flag set",
        ),
        (
            {
                "telemetry_source": "measured",
                "has_infra_invalid": False,
                "model_calls": 1,
                "token_usage": 0,  # model calls > 0 but tokens <= 0 (outlier/missing)
                "wall_time_ms": 1500,
                "provider_costs": 0.05,
                "overhead_ms": 200,
            },
            "Model call with zero token usage",
        ),
        (
            {
                "telemetry_source": "measured",
                "has_infra_invalid": False,
                "model_calls": 1,
                "token_usage": 1234,
                "gateway_token_outlier_reason": "stats_outlier_possible_cumulative",  # Outlier detected
                "wall_time_ms": 1500,
                "provider_costs": 0.05,
                "overhead_ms": 200,
            },
            "Stats outlier possible cumulative",
        ),
        (
            {
                "telemetry_source": "measured",
                "has_infra_invalid": False,
                "model_calls": 1,
                "token_usage": 1234,
                # Missing required keys (overhead_ms is missing)
                "wall_time_ms": 1500,
                "provider_costs": 0.05,
            },
            "Missing overhead_ms key",
        ),
    ],
)
def test_public_claim_safe_contract_fails_on_boundary_violations(invalid_telemetry, reason):
    """M3 Layer 3: Verify strict fail-closed boundary enforcement on unmeasured,

    corrupt, outlier, or missing telemetry fields.
    """
    receipt = CapabilityReceipt(
        name="artifact_gate",
        selected=True,
        invoked=True,
        evidence_present=True,
        gate_passed=True,
        outcome_contributed=True,
        evidence_alignment=True,
        telemetries=invalid_telemetry,
    )

    assert receipt.public_claim_safe is False, f"Boundary violation check failed: {reason}"
